(4982864, 725440, 63806, '<td valign="top">Nice perspective and I love the title.. could be a little bit sharper</td>', 'Nice perspective and I love the title.. could be a little bit sharper', '2008-10-01 01:22:17.000000', NULL, 1),
(4982896, 726525, 54645, '<td valign="top">What a great image. Nice use of complementing colors. I''m sure this will score very high.</td>', 'What a great image. Nice use of complementing colors. I''m sure this will score very high.', '2008-10-01 01:25:20.000000', NULL, 1),
(4982910, 726035, 54645, '<td valign="top">Turned out fantastic. Love the complementing background. It''s almost like a well placed frame or vignette.</td>', 'Turned out fantastic. Love the complementing background. It''s almost like a well placed frame or vignette.', '2008-10-01 01:27:03.000000', NULL, 1),
(4982922, 727096, 54645, '<td valign="top">Cute expression, but the composition just missed in my opinion. I don''t like the negative space behind and right. Fantastic lighting, nice bright eyes. The parents will love this.</td>', 'Cute expression, but the composition just missed in my opinion. I don''t like the negative space behind and right. Fantastic lighting, nice bright eyes. The parents will love this.', '2008-10-01 01:28:15.000000', NULL, 1),
