(4993386, 727072, 72268, '<td valign="top">My fav so far. 9</td>', 'My fav so far. 9', '2008-10-05 16:40:47.000000', NULL, 1),
(4993394, 726878, 58247, '<td valign="top">Lovely image that''s full of life. Your lighting seems spot on to me and the mix of colors in the image really complement each other. Great job!</td>', 'Lovely image that''s full of life. Your lighting seems spot on to me and the mix of colors in the image really complement each other. Great job!', '2008-10-05 16:45:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4993395, 726824, 58247, '<td valign="top">Another good one that should do well Mr. Toole. I need to get back to shooting more and practice my lighting.  Your abilities are surpassing mine!</td>', 'Another good one that should do well Mr. Toole. I need to get back to shooting more and practice my lighting.  Your abilities are surpassing mine!', '2008-10-05 16:45:12.000000', NULL, 1),
(4993397, 726538, 58247, '<td valign="top">I really feel the emotion portrayed in this shot.</td>', 'I really feel the emotion portrayed in this shot.', '2008-10-05 16:47:51.000000', NULL, 1),
(4993402, 725351, 70661, '<td valign="top">You''ve captured a great smile here and the eyes look awesome. The head is so high up in the photo though that his body seems extremely long. The dark suit blends in with the background so it kind of looks like a floating head with a collar and tie. I would have given you a much higher score if it wasn''t cropped so close to the top and maybe more cropped off of the bottom.</td>', 'You''ve captured a great smile here and the eyes look awesome. The head is so high up in the photo though that his body seems extremely long. The dark suit blends in with the background so it kind of looks like a floating head with a collar and tie. I would have given you a much higher score if it wasn''t cropped so close to the top and maybe more cropped off of the bottom.', '2008-10-05 16:48:47.000000', NULL, 1),
(4993535, 724934, 25355, '<td valign="top">Serious? It''s a bit creepy to me. ;-Þ</td>', 'Serious? It''s a bit creepy to me. ;-Þ', '2008-10-05 17:45:27.000000', NULL, 1),
(4993622, 727130, 66201, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2008-10-05 19:15:06.000000', NULL, 1),
(4993626, 726411, 66201, '<td valign="top">Great character and impact!</td>', 'Great character and impact!', '2008-10-05 19:19:10.000000', NULL, 1),
(4993642, 726003, 66201, '<td valign="top">really beautiful image - striking composition!</td>', 'really beautiful image - striking composition!', '2008-10-05 19:31:13.000000', NULL, 1),
(4993644, 727016, 66201, '<td valign="top">amazing makeup, and front lighting. I think your backdrop has let you down though.</td>', 'amazing makeup, and front lighting. I think your backdrop has let you down though.', '2008-10-05 19:32:30.000000', NULL, 1),
(4993645, 726186, 66201, '<td valign="top">Dr Phil?</td>', 'Dr Phil?', '2008-10-05 19:32:52.000000', NULL, 1),
(4993646, 726641, 66201, '<td valign="top">Fantastic tones and composition. All round a very pleasing image!</td>', 'Fantastic tones and composition. All round a very pleasing image!', '2008-10-05 19:33:46.000000', NULL, 1),
(4993710, 726159, 36382, '<td valign="top">It seems to have a seventies feel to me.  I don''t know why though.  Excellent image.</td>', 'It seems to have a seventies feel to me.  I don''t know why though.  Excellent image.', '2008-10-05 21:17:37.000000', NULL, 1),
(4993711, 727092, 36382, '<td valign="top">Excellent expression.  Excellent image.</td>', 'Excellent expression.  Excellent image.', '2008-10-05 21:17:58.000000', NULL, 1),
(4993713, 726628, 36382, '<td valign="top">I would like to see a little more light on the right hand side.  Still gave high marks though.  I think it is one of the best of the challenge.</td>', 'I would like to see a little more light on the right hand side.  Still gave high marks though.  I think it is one of the best of the challenge.', '2008-10-05 21:20:35.000000', NULL, 1),
(4993717, 726976, 36382, '<td valign="top">Good picture but colors seem a bit off.  Her face is way too pink.  Easily fixed though. :)</td>', 'Good picture but colors seem a bit off.  Her face is way too pink.  Easily fixed though. :)', '2008-10-05 21:22:54.000000', NULL, 1),
(4993719, 725844, 36382, '<td valign="top">This is  beautiful.  I especially like the color of the background.  This would not look out of place to me in any "upscale" magazine.</td>', 'This is  beautiful.  I especially like the color of the background.  This would not look out of place to me in any "upscale" magazine.', '2008-10-05 21:23:46.000000', NULL, 1),
(4993782, 727108, 53594, '<td valign="top">I really like this image. Good focus, lighting, composition and facial expression. My only dislike is the out of focus flower stems and vase. Definitely in the TOP TEN. Good job!!!!!</td>', 'I really like this image. Good focus, lighting, composition and facial expression. My only dislike is the out of focus flower stems and vase. Definitely in the TOP TEN. Good job!!!!!', '2008-10-05 22:14:37.000000', NULL, 1),
(4993787, 725844, 53594, '<td valign="top">One of my favorites in this challenge. I truly expect this image to be in the "Top Ten".</td>', 'One of my favorites in this challenge. I truly expect this image to be in the "Top Ten".', '2008-10-05 22:18:59.000000', NULL, 1),
(4993871, 727126, 88204, '<td valign="top">I love the shallow depth of field and the bright smile and eyes. Nice expression too.</td>', 'I love the shallow depth of field and the bright smile and eyes. Nice expression too.', '2008-10-05 23:31:07.000000', NULL, 1),
(4993872, 725888, 88204, '<td valign="top">Studio portrait?</td>', 'Studio portrait?', '2008-10-05 23:31:41.000000', NULL, 1),
(4993873, 727023, 88204, '<td valign="top">Great warm lighting and back lighting. I love the textured background as well.</td>', 'Great warm lighting and back lighting. I love the textured background as well.', '2008-10-05 23:32:19.000000', NULL, 1),
(4993876, 725129, 88204, '<td valign="top">Studio portrait?</td>', 'Studio portrait?', '2008-10-05 23:33:54.000000', NULL, 1),
(4993881, 727107, 59415, '<td valign="top">Um, I can see up her skirt.</td>', 'Um, I can see up her skirt.', '2008-10-05 23:38:55.000000', NULL, 1),
(4993885, 726431, 53594, '<td valign="top">Loss of details in the highlights but overall a very good image. Good Luck</td>', 'Loss of details in the highlights but overall a very good image. Good Luck', '2008-10-05 23:42:05.000000', NULL, 1),
(4993889, 726967, 14437, '<td valign="top">Great lighting!</td>', 'Great lighting!', '2008-10-05 23:43:53.000000', NULL, 1),
(4993892, 726385, 53594, '<td valign="top">She is adorable. This a wonderful studio portrait. Well done!</td>', 'She is adorable. This a wonderful studio portrait. Well done!', '2008-10-05 23:44:16.000000', NULL, 1),
(4993894, 726038, 59415, '<td valign="top">I''m a PC.</td>', 'I''m a PC.', '2008-10-05 23:46:09.000000', NULL, 1),
(4993901, 725532, 59415, '<td valign="top">Your Jesus?</td>', 'Your Jesus?', '2008-10-05 23:50:23.000000', NULL, 1),
(4993902, 726709, 59415, '<td valign="top">One of my favorites from this group.</td>', 'One of my favorites from this group.', '2008-10-05 23:51:12.000000', NULL, 1),
(4993903, 725401, 59415, '<td valign="top">One of my favorites from this group.</td>', 'One of my favorites from this group.', '2008-10-05 23:51:25.000000', NULL, 1),
(4993904, 725844, 59415, '<td valign="top">I think this is a decent photo.  I am not perfectly fond of the crop or the tones, but I gave it a 7.</td>', 'I think this is a decent photo.  I am not perfectly fond of the crop or the tones, but I gave it a 7.', '2008-10-05 23:52:01.000000', NULL, 1),
(4993905, 725469, 59415, '<td valign="top">I think this is a well lit family portrait.  I would have like to have seen a bit more of a shallow DOF on a further away background to blur it out a bit.</td>', 'I think this is a well lit family portrait.  I would have like to have seen a bit more of a shallow DOF on a further away background to blur it out a bit.', '2008-10-05 23:52:38.000000', NULL, 1),
(4993906, 726385, 59415, '<td valign="top">A very nice all around portrait photo.</td>', 'A very nice all around portrait photo.', '2008-10-05 23:52:50.000000', NULL, 1),
(4993907, 726629, 59415, '<td valign="top">I think this is nice, but the plant sort of got in the way.  7</td>', 'I think this is nice, but the plant sort of got in the way.  7', '2008-10-05 23:53:11.000000', NULL, 1),
(4993908, 726868, 59415, '<td valign="top">Very well lit portrait. 7</td>', 'Very well lit portrait. 7', '2008-10-05 23:53:23.000000', NULL, 1),
(4993909, 726985, 59415, '<td valign="top">I think this is a very well lit portrait.</td>', 'I think this is a very well lit portrait.', '2008-10-05 23:53:35.000000', NULL, 1),
(4993910, 726627, 23002, '<td valign="top">Lighting is flat.  I think having the one shoulder cropped off makes it look odd, and cropping the top of the head doesnot help either.  I think instead of what looks like 3 lights and a reflector I would have taken one of the lights and put it on the background instead to make it white instead of grey.<br/> <br/>That critical stuff aside, she is a beautiful model with wonderful skin and the processing is very nice. 5</td>', 'Lighting is flat.  I think having the one shoulder cropped off makes it look odd, and cropping the top of the head doesnot help either.  I think instead of what looks like 3 lights and a reflector I would have taken one of the lights and put it on the background instead to make it white instead of grey. That critical stuff aside, she is a beautiful model with wonderful skin and the processing is very nice. 5', '2008-10-05 23:53:51.000000', NULL, 1),
(4993911, 727064, 59415, '<td valign="top">A very well lit portrait.  I wish I could have seen her hands, or they were cropped a bit different.</td>', 'A very well lit portrait.  I wish I could have seen her hands, or they were cropped a bit different.', '2008-10-05 23:54:09.000000', NULL, 1),
(4993912, 726573, 59415, '<td valign="top">The dramatic lighting worked for me on this one.</td>', 'The dramatic lighting worked for me on this one.', '2008-10-05 23:54:24.000000', NULL, 1),
(4993914, 726890, 59415, '<td valign="top">You need a DPC hat.</td>', 'You need a DPC hat.', '2008-10-05 23:54:53.000000', NULL, 1),
(4993915, 727009, 23002, '<td valign="top">Nice exposure, tone and colour.  Nice lighting that is not flat.  Great skin on your model. 7</td>', 'Nice exposure, tone and colour.  Nice lighting that is not flat.  Great skin on your model. 7', '2008-10-05 23:55:03.000000', NULL, 1),
(4993916, 726411, 59415, '<td valign="top">I think the tones and lighting are nice here.</td>', 'I think the tones and lighting are nice here.', '2008-10-05 23:55:06.000000', NULL, 1),
(4993917, 725764, 59415, '<td valign="top">A nice little portrait.7</td>', 'A nice little portrait.7', '2008-10-05 23:55:43.000000', NULL, 1),
(4993918, 727009, 59415, '<td valign="top">This is a nice well lit portrait.</td>', 'This is a nice well lit portrait.', '2008-10-05 23:56:01.000000', NULL, 1),
(4993919, 727197, 59415, '<td valign="top">Very professionally done portrait.</td>', 'Very professionally done portrait.', '2008-10-05 23:56:17.000000', NULL, 1),
(4993920, 726135, 59415, '<td valign="top">Now we have a party.</td>', 'Now we have a party.', '2008-10-05 23:56:26.000000', NULL, 1),
(4993921, 726573, 23002, '<td valign="top">the severe crop to her head is very distracting here, as is the fact that her one eye is almost totally dark.  I think a reflector to open up that side of the face, and a more normal crop would have made a huge difference here.<br/> <br/>Still she is a very pleasing model with nice skin tones. 5</td>', 'the severe crop to her head is very distracting here, as is the fact that her one eye is almost totally dark.  I think a reflector to open up that side of the face, and a more normal crop would have made a huge difference here. Still she is a very pleasing model with nice skin tones. 5', '2008-10-05 23:56:52.000000', NULL, 1),
(4993924, 726941, 23002, '<td valign="top">Ok, I am going to guess that this is one light with a reflector.  <br/>The first issue is that she is to close to the background so that the shadow is visible behind her.  The main light is to strong causing the shine on her skin and the harsh shadow from the shirt on her neck area.  Could you have diffused the main light with an umbrella or bouncing it somehow?  The reflector must not be close enough to the model to have the desired effect.<br/> <br/>I think it is a great practice shot for studio portrait, but is lacking in some areas.  Keep up the shooting and you will have it right soon. :) 5</td>', 'Ok, I am going to guess that this is one light with a reflector.  The first issue is that she is to close to the background so that the shadow is visible behind her.  The main light is to strong causing the shine on her skin and the harsh shadow from the shirt on her neck area.  Could you have diffused the main light with an umbrella or bouncing it somehow?  The reflector must not be close enough to the model to have the desired effect. I think it is a great practice shot for studio portrait, but is lacking in some areas.  Keep up the shooting and you will have it right soon. :) 5', '2008-10-06 00:00:22.000000', NULL, 1),
(4993928, 725585, 23002, '<td valign="top">ok, single light to left of camera.  The light appears very harsh, and it seems you exposed for the light on the model''s face, not his outstretched hand which now seems overexposed.  I am sorry but  I just do not think it is a great way to portray someone. :( 3</td>', 'ok, single light to left of camera.  The light appears very harsh, and it seems you exposed for the light on the model''s face, not his outstretched hand which now seems overexposed.  I am sorry but  I just do not think it is a great way to portray someone. :( 3', '2008-10-06 00:02:10.000000', NULL, 1),
(4993930, 725769, 23002, '<td valign="top">Because of the very deliberate lighting here I will give you the benefit of the doubt that this was in fact taken indoors and not outdoors.<br/> <br/>Either way a reflector would have helped fill in the nasty shadows happening here. I like the idea of a grungy type photo, but the busy clothing against a busy background just makes things confusing.  Also the model looking up with her eyes make it look they are rolled back in her head.<br/> <br/>Overall I like the concept, not the execution. 5</td>', 'Because of the very deliberate lighting here I will give you the benefit of the doubt that this was in fact taken indoors and not outdoors. Either way a reflector would have helped fill in the nasty shadows happening here. I like the idea of a grungy type photo, but the busy clothing against a busy background just makes things confusing.  Also the model looking up with her eyes make it look they are rolled back in her head. Overall I like the concept, not the execution. 5', '2008-10-06 00:04:48.000000', NULL, 1),
(4993931, 725844, 14437, '<td valign="top">Great expression and composition. The lighting is perfect. 10</td>', 'Great expression and composition. The lighting is perfect. 10', '2008-10-06 00:04:57.000000', NULL, 1),
(4993933, 726986, 23002, '<td valign="top">Nice skin.  The lighting is far too flat however, and the blue scarf is very distracting. 4</td>', 'Nice skin.  The lighting is far too flat however, and the blue scarf is very distracting. 4', '2008-10-06 00:05:55.000000', NULL, 1),
(4993938, 726525, 23002, '<td valign="top">A very nice studio shot.  It does however suffer from slight overexposure (the glove is burned out on my calibrated monitor) and the main light is too high.  See how the shadow from the nose goes all the way down her face to the bottom of her chin?  It should go so far as to touch the lips.  Nice job on the fill light and a nice job lighting the white backdrop.  The model has a great expression, although it is generally a good idea to ask them to just barely touch the hand to the face, not put any weight on it becuase it distorts the facial features a bit.  <br/> <br/>Overall a very nice shot. 6</td>', 'A very nice studio shot.  It does however suffer from slight overexposure (the glove is burned out on my calibrated monitor) and the main light is too high.  See how the shadow from the nose goes all the way down her face to the bottom of her chin?  It should go so far as to touch the lips.  Nice job on the fill light and a nice job lighting the white backdrop.  The model has a great expression, although it is generally a good idea to ask them to just barely touch the hand to the face, not put any weight on it becuase it distorts the facial features a bit.   Overall a very nice shot. 6', '2008-10-06 00:09:35.000000', NULL, 1),
(4993943, 727211, 23002, '<td valign="top">This does not look like an in studio portrait. The crop of the head in this case does nothing to enhance the photo.  The collar sticking up in the left of the shot is very distracting.  The skin tones are pleasing however and the exposure is good.</td>', 'This does not look like an in studio portrait. The crop of the head in this case does nothing to enhance the photo.  The collar sticking up in the left of the shot is very distracting.  The skin tones are pleasing however and the exposure is good.', '2008-10-06 00:11:13.000000', NULL, 1),
(4993946, 727107, 23002, '<td valign="top">If the background is supposed to be black, it is not quite dark enough on my calibrated monitor.  The dark hair blends in against the background and needs a hair light.  Her pose just looks too awkward to me, and the lighting is very harsh as can be seen by the shadows on her face.<br/> <br/> <br/>On the good side she is a very attractive model, it is taken indoors, and I am sure it would have looked much different if this challenge was done with advanced ruleset instead of basic which makes things very tough for portraits.</td>', 'If the background is supposed to be black, it is not quite dark enough on my calibrated monitor.  The dark hair blends in against the background and needs a hair light.  Her pose just looks too awkward to me, and the lighting is very harsh as can be seen by the shadows on her face.  On the good side she is a very attractive model, it is taken indoors, and I am sure it would have looked much different if this challenge was done with advanced ruleset instead of basic which makes things very tough for portraits.', '2008-10-06 00:14:22.000000', NULL, 1),
(4993948, 727109, 60495, '<td valign="top">This is one of those shots where I look at it and go back and forth whether I like the crop or not which to me is kind of good because it makes you stop and study it further. I love the skin tones and the way the red lipstick stands out and the curls coming through the middle of the face make the shot. Good job!</td>', 'This is one of those shots where I look at it and go back and forth whether I like the crop or not which to me is kind of good because it makes you stop and study it further. I love the skin tones and the way the red lipstick stands out and the curls coming through the middle of the face make the shot. Good job!', '2008-10-06 00:17:33.000000', NULL, 1),
(4993949, 726492, 23002, '<td valign="top">This has the feel of a shot that was taken a bit wider and then rotated and cropped after the fact.  Either that or your camera angle is way to high for the lighting, since the shadow from your main light is almost going directly to the side of her face (look at the nose shadow) instead of down on a 45 degree angle.  Great job in separating th dark hair and outfit from the background.  Nice exposure.</td>', 'This has the feel of a shot that was taken a bit wider and then rotated and cropped after the fact.  Either that or your camera angle is way to high for the lighting, since the shadow from your main light is almost going directly to the side of her face (look at the nose shadow) instead of down on a 45 degree angle.  Great job in separating th dark hair and outfit from the background.  Nice exposure.', '2008-10-06 00:17:51.000000', NULL, 1),
(4993950, 727194, 23002, '<td valign="top">Sorry I do not get it.  This is not flattering to your model in any way.</td>', 'Sorry I do not get it.  This is not flattering to your model in any way.', '2008-10-06 00:18:33.000000', NULL, 1),
(4993952, 725832, 23002, '<td valign="top">focus is soft and not a very flattering shot of the little guy.</td>', 'focus is soft and not a very flattering shot of the little guy.', '2008-10-06 00:19:29.000000', NULL, 1),
(4993953, 726491, 60495, '<td valign="top">His first digital shot, that''s a keeper!</td>', 'His first digital shot, that''s a keeper!', '2008-10-06 00:20:57.000000', NULL, 1),
(4993954, 725817, 23002, '<td valign="top">Nice use of side lighting to bring out the facial texture to make him look masculine.  However it is still a bit too dark and a bit of a reflector fill woul have helped.  It appears that you can see a sharpening halo around the subject.  Overall nice shot.</td>', 'Nice use of side lighting to bring out the facial texture to make him look masculine.  However it is still a bit too dark and a bit of a reflector fill woul have helped.  It appears that you can see a sharpening halo around the subject.  Overall nice shot.', '2008-10-06 00:21:35.000000', NULL, 1),
(4993956, 726787, 23002, '<td valign="top">This has nothing to do with studio portrait at all.  I hope that you are intentionally going for the brown cause you just might get it.</td>', 'This has nothing to do with studio portrait at all.  I hope that you are intentionally going for the brown cause you just might get it.', '2008-10-06 00:22:09.000000', NULL, 1),
(4993958, 726068, 23002, '<td valign="top">A very awkward crop.  It is a shame his face and nose were not washed first.  Sorry but it is distracting and not flattering at all.</td>', 'A very awkward crop.  It is a shame his face and nose were not washed first.  Sorry but it is distracting and not flattering at all.', '2008-10-06 00:23:04.000000', NULL, 1),
(4993960, 727084, 23002, '<td valign="top">The dry ice is nice, but it does not look much like a studio portrait.</td>', 'The dry ice is nice, but it does not look much like a studio portrait.', '2008-10-06 00:23:52.000000', NULL, 1),
(4993963, 726979, 23002, '<td valign="top">I am sure you love Braden very much and rightfully so.  However an overexposed, oversaturated picture of a crying baby is not pleasant to look at.  Sorry, better luck next time.</td>', 'I am sure you love Braden very much and rightfully so.  However an overexposed, oversaturated picture of a crying baby is not pleasant to look at.  Sorry, better luck next time.', '2008-10-06 00:24:57.000000', NULL, 1),
(4993964, 725923, 23002, '<td valign="top">This is beautiful.  It would have scored at least an 8 from me if he was not missing the tip of his ear.  As it is you are still getting a nice 6 from me.  Great exposure and nice soft light.  Woof!</td>', 'This is beautiful.  It would have scored at least an 8 from me if he was not missing the tip of his ear.  As it is you are still getting a nice 6 from me.  Great exposure and nice soft light.  Woof!', '2008-10-06 00:25:54.000000', NULL, 1),
(4993965, 727027, 23002, '<td valign="top">Such a great model and such a poor location to take the photo. Sorry, but the location is very distracting and ruins a nice photo of a very interesting boy.</td>', 'Such a great model and such a poor location to take the photo. Sorry, but the location is very distracting and ruins a nice photo of a very interesting boy.', '2008-10-06 00:27:01.000000', NULL, 1),
(4993967, 725844, 23002, '<td valign="top">I think the crop is very awkward, both the crop at the top of her head and missing the one shoulder.  The lighting is great.  The angle of the camer is not flattering for her though, since it is an "up your nose" shot and also puts too much emphasis on her ear.  She also appears to be a bit of a sickly green/yellow on my calibrated monitor.<br/> <br/>Great lighting and model.</td>', 'I think the crop is very awkward, both the crop at the top of her head and missing the one shoulder.  The lighting is great.  The angle of the camer is not flattering for her though, since it is an "up your nose" shot and also puts too much emphasis on her ear.  She also appears to be a bit of a sickly green/yellow on my calibrated monitor. Great lighting and model.', '2008-10-06 00:29:01.000000', NULL, 1),
(4993987, 727016, 60495, '<td valign="top">Nice shot, only thing I think I would change is the back ground color, the color of the back ground to me tends to clash with the skin tones rather than enhance or compliment. Also I think evening out the lighting on the eyes would help make this a killer shot.</td>', 'Nice shot, only thing I think I would change is the back ground color, the color of the back ground to me tends to clash with the skin tones rather than enhance or compliment. Also I think evening out the lighting on the eyes would help make this a killer shot.', '2008-10-06 00:44:15.000000', NULL, 1),
(4993990, 727113, 94265, '<td valign="top">The warm lighting looks beautiful on her, I love that the nudity is implied and manages to be elegant, that''s not something everyone can achieve. Well done.</td>', 'The warm lighting looks beautiful on her, I love that the nudity is implied and manages to be elegant, that''s not something everyone can achieve. Well done.', '2008-10-06 00:45:53.000000', NULL, 1),
(4993991, 725844, 94265, '<td valign="top">I adore the colour scheme here and her eye make-up is awesome, beautiful model.</td>', 'I adore the colour scheme here and her eye make-up is awesome, beautiful model.', '2008-10-06 00:46:31.000000', NULL, 1),
(4993997, 727096, 94265, '<td valign="top">This is so damn cute! I love that the wee hat is too big and that happy little smile, little dimples too! It''s so natural, just like a kiddie portrait should be.</td>', 'This is so damn cute! I love that the wee hat is too big and that happy little smile, little dimples too! It''s so natural, just like a kiddie portrait should be.', '2008-10-06 00:47:26.000000', NULL, 1),
(4993998, 726717, 94265, '<td valign="top">This looks quite professional, like something from the cover of Maxim or a biker magazine but not the usual sleazy fare. The lighting is great.</td>', 'This looks quite professional, like something from the cover of Maxim or a biker magazine but not the usual sleazy fare. The lighting is great.', '2008-10-06 00:48:38.000000', NULL, 1),
(4994000, 726967, 94265, '<td valign="top">I love the dark lighting, gives this a very moody look, along with that great pout and the groovy tats.</td>', 'I love the dark lighting, gives this a very moody look, along with that great pout and the groovy tats.', '2008-10-06 00:49:22.000000', NULL, 1),
(4994001, 725253, 94265, '<td valign="top">Really well lit, good crop too. It''s a very honest portrait, right up front, not hiding anything. Pretty coloured eyes too.</td>', 'Really well lit, good crop too. It''s a very honest portrait, right up front, not hiding anything. Pretty coloured eyes too.', '2008-10-06 00:50:21.000000', NULL, 1),
